import sqlite3
from contextlib import closing

from agents import function_tool

DB_PATH = "cms.db"


@function_tool
def transfer_post_ownership(post_id: int, new_author_id: int) -> dict:
    with closing(sqlite3.connect(DB_PATH)) as conn:
        with conn:
            row = conn.execute(
                "SELECT author_id FROM posts WHERE id = ?", (post_id,)
            ).fetchone()
            if row is None:
                return {"ok": False, "error": "post not found"}
            user = conn.execute(
                "SELECT id FROM users WHERE id = ?", (new_author_id,)
            ).fetchone()
            if user is None:
                return {"ok": False, "error": "user not found"}
            conn.execute(
                "UPDATE posts SET author_id = ? WHERE id = ?",
                (new_author_id, post_id),
            )
            conn.execute(
                "INSERT OR IGNORE INTO post_editors (post_id, user_id) VALUES (?, ?)",
                (post_id, new_author_id),
            )
            editors = [
                r[0]
                for r in conn.execute(
                    "SELECT user_id FROM post_editors WHERE post_id = ?", (post_id,)
                )
            ]
    return {
        "ok": True,
        "previous_author_id": row[0],
        "new_author_id": new_author_id,
        "editors": editors,
    }
